-- Flyway manages this migration transaction.
-- Real Seoul Gangseo places: 40 restaurants, 30 coffee shops, 30 clinics.
-- Source: Seoul Open Data Plaza, Gangseo-gu (KOGL Type 1, attribution required).
-- https://data.seoul.go.kr/dataList/OA-18667/S/1/datasetView.do
-- https://data.seoul.go.kr/dataList/OA-18692/S/1/datasetView.do
-- https://data.seoul.go.kr/dataList/OA-16229/S/1/datasetView.do
-- Retrieved: 2026-11-05. Source EPSG:5174 -> WGS84 EPSG:4326.
-- Only source status 01 (active). Snapshot data; not a live business-status guarantee.
-- Re-running skips existing (road_name_address, name) and never overwrites existing places.
CREATE TEMP TABLE gangseo_place_seed (
    source_dataset text, source_id text, name text, category_code text,
    road_name_address text, lot_number_address text, zip_code text, phone text,
    x double precision, y double precision
) ON COMMIT DROP;

DO $$
BEGIN
    IF (SELECT count(*) FROM gangseo_place_seed) <> 100 THEN
        RAISE EXCEPTION 'Expected 100 source places';
    END IF;
    IF EXISTS (
        SELECT 1 FROM gangseo_place_seed s
        CROSS JOIN LATERAL (SELECT ST_Transform(ST_SetSRID(ST_MakePoint(s.x, s.y), 5174), 4326) AS geom) p
        WHERE NOT (ST_Y(p.geom) BETWEEN 37.50 AND 37.65 AND ST_X(p.geom) BETWEEN 126.70 AND 126.95)
           OR s.road_name_address NOT LIKE '서울특별시 강서구 %'
           OR NOT EXISTS (
               SELECT 1 FROM tb_cmn_code c JOIN tb_cmn_code root ON root.id = c.parent_id
               WHERE root.parent_id IS NULL AND root.code = 'PLACE_CATEGORY'
                 AND c.code = s.category_code AND c.state = 'ACTIVE'
           )
    ) THEN
        RAISE EXCEPTION 'Invalid source coordinates, address, or category';
    END IF;
END $$;

SELECT ST_Transform(ST_SetSRID(ST_MakePoint(x, y), 5174), 4326)::geography,
       name, category_code, road_name_address, lot_number_address, zip_code, phone
FROM gangseo_place_seed
ON CONFLICT (road_name_address, name) DO NOTHING;

